--- 初始化手机滚动列表的页数提示
---@param num any
function HomeOtherNode:InitPageHintPoint(num)
    local parent = self.controller.transform:Find("TurnGroup")
    for i = 0, 3, 1 do
        local child = parent:GetChild(i)
        KTool.SetActive(child, i < num)
    end
end

--- 初设置手机滚动列表的页数提示
---@param index any
function HomeOtherNode:SelectPageHintPoint(index)
    local parent = self.controller.transform:Find("TurnGroup")
    for i = 0, 3, 1 do
        local child = parent:GetChild(i)
        local simg = child:GetComponent(typeof(UISwitchImage))
        simg.Status = i == index and 2 or 1
    end
end

function HomeOtherNode:FillMusicInfo()
    local id = playerComponent:GetCurrentMusicId()
    if checkNumber(id) <= 0 then
        return
    end

    ---@type MusicPlayerVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", id)
    if not vo then
        return
    end
    CfUtils.FillImage(self.ImgIcon, vo.coverImg)

    ---@type UIActionPromptUpItemNode
    local scr = CfUtils.GetLuaScr(self.MaskText, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
    if scr then
        scr:Refresh(vo.name, false)
    end
end

function HomeOtherNode:UpdateOtherRedPoint()
    for _, v in pairs(CfUtils.GetCfTable(AutoIds.IdSetting1860) or {}) do
        local systemToggleId = parse_number(v, "id")
        if systemToggleId == Constants.SystemToggleIds.Id907 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.Handbook
        elseif systemToggleId == Constants.SystemToggleIds.Id200 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.Backpack
        elseif systemToggleId == Constants.SystemToggleIds.Id201 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.Mail
        elseif systemToggleId == Constants.SystemToggleIds.Id2018 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.RankCollection
        elseif systemToggleId == Constants.SystemToggleIds.Id229 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.Friend
        elseif systemToggleId == Constants.SystemToggleIds.Id250 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.ConvertExchange
        elseif systemToggleId == Constants.SystemToggleIds.Id350 then
            self._otherRedPointMap[systemToggleId] = Constants.RedPointConst.ConnectSever
        end
    end
end

function HomeOtherNode:InitPagesData()
    local voList = CfUtils.GetCfTable(AutoIds.IdSetting1860)
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    ---@type UserComponent
    local userCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if SDKService:IsZm() or
    (
      ((KTool.IsMobile() and checkInt(userCom.userInfo.isGameCenter) > 0) or (not KTool.IsMobile()))    
      and SDKService:IsForeignSDK() and (not SDKService:IsJP() and (not GameUtils.GetChannelId() == 5045) )
    )
     and checkInt(IS_REVIEW_INT) <= 0 then        
        self.pagesData = GameUtils.SplitTable(voList, 9)
    else 
        -- 如果不是智明 并且没有直接跳到用户中心等条件
        local newTable = {}
        local index = 0
        local count = 9
        for i, v in pairs(voList) do
            local systemToggleId = parse_number(v, "id")
            if ThirdDownloadManager:IsNotDwonloadingEnd() then
                if not (systemToggleId == Constants.SystemToggleIds.Id907 or systemToggleId == Constants.SystemToggleIds.Id350 or systemToggleId == Constants.SystemToggleIds.Id29) then
                    if count >= 9 then
                        count = 0
                        index = index + 1
                        newTable[index] = {}
                    end
                    table.insert(newTable[index], v)
                    count = count + 1
                end
            else
                if not (systemToggleId == Constants.SystemToggleIds.Id350 or (SDKService:GetInstance():IsDuoLe() and IS_REVIEW_INT > 0 and systemToggleId == Constants.SystemToggleIds.Id907 ))   then
                    if count >= 9 then
                        count = 0
                        index = index + 1
                        newTable[index] = {}
                    end
                    table.insert(newTable[index], v)
                    count = count + 1
                end
            end
        end
        self.pagesData = newTable
    end    
end

---刷新滚动页面
function HomeOtherNode:RefreshLoopListView(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function HomeOtherNode:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("ItemCell")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true

        -- 这里一个cell是一个页面，一个页面有9个按钮
        local data = self.pagesData[index + 1]
        if isNotNull(data) then
            cell.name = PageCellName .. (index+1)
            self:CreatePage(cell, data)
        end
    end

    return cell
end

--绘制其他按钮（初次创建）
function HomeOtherNode:CreatePage(cell, btnList)
    local name = self.ButtonNode.name
    KTool.SetActive(self.ButtonNode.gameObject, false)
    local grid = cell.transform:Find("FunctionIconGrid")
    local animCell = cell:GetComponent(typeof(CS.UnityEngine.Animation))
    animCell:Play("UIHomeView_OtherButtonPOP_ItemCell_Entry")
    for k, v in ipairs(btnList) do
        local systemToggleId = parse_number(v, "id")
        if systemToggleId ~= Constants.SystemToggleIds.Id242 then
            local buttonName = string.format("%s%s", name, systemToggleId)
            local go = CfUtils.InstantiateGo(self.ButtonNode.gameObject, grid)
            if go then
                go.name = buttonName
                if systemToggleId ~= Constants.SystemToggleIds.Id242 then
                    KTool.SetActive(go, true)
                end
                local path = ParseUtils.ParsePathName(v, "actionIcon")
                CfUtils.FillImage(go.transform:Find("Transparent/ImgIcon"), path)
                CfUtils.FillText(go.transform:Find("Transparent/TxtTitle"), parse_localizeText(v, "name"))
               
                if isNull(self.btnList) then
                    self.btnList = {}
                end
                self.btnList[systemToggleId] = go

                self:RefreshBtn(go, systemToggleId)
            end
        end
    end

    --local rt = self.OtherButtonPOP.transform:Find("Bg"):GetComponent(typeof(RectTransform))
    --if unlockCount <= 5 then
    --    local num = (559 - unlockCount * (115)) / 2
    --    rt.offsetMin = Vector2(num, 0)
    --    rt.offsetMax = Vector2(-num, 0)
    --else
    --    rt.offsetMin = Vector2(0, 0)
    --    rt.offsetMax = Vector2(0, 0)
    --end
end


function HomeOtherNode:RefreshBtn(go, systemToggleId)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(systemToggleId)
    if isUnlock then
        -- 绑定红点
        local redKey = self._otherRedPointMap[systemToggleId]
        if redKey then
            GameUtils.BindRedPoint(redKey, go, true)
        end
        -- 点击事件
        if systemToggleId == Constants.SystemToggleIds.Id242 then
            ----社区的特殊处理
            ---@type Engine.Modules.LuaBehaviour
            local luaBehaviour = KTool.GetComponent(go.gameObject, typeof(CS.Engine.Modules.LuaBehaviour))
            if isNull(luaBehaviour) then
                luaBehaviour = AddLuaBehaviour(go.gameObject, "Game.Behaviours.PlayerCommunityButton")
            end
            luaBehaviour.Env:Awake()
            GameUtils.SetCommunityClick(go.gameObject, 1)
            --luaBehaviour.Env:SetJumpId(1)
            ---@type Game.Native.Common.PlayerCommunityButton
            --local communityButton = KTool.GetOrAddComponent(go.gameObject, typeof(CS.Game.Native.Common.PlayerCommunityButton))
            --communityButton.id = 1
        else
            GameUtils.RefeshSystemToggleId(go, systemToggleId)
            if systemToggleId == Constants.SystemToggleIds.Id229 then
                -- GameUtils.BindRedPoint(Constants.RedPointConst.Friend, go, true)
                self:SetReverseButtonAction(go, function()
                    KCookie.Set("FriendMain", 1)--从这边打开默认选中好友列表
                    xRecord.record('3-014')
                    self:OpenDialogAction(Constants.UITypeIds.FriendMain, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id203 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.UISettingDialog, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id202 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.UINoticeDialog, {}, nil, true)
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id223 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.UIFeelingShopDialog, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id29 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.TrainFieldChooseModeDialog, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id108 then
                ----旧的合成不需要了，删除
                --self:SetReverseButtonAction(go, function()
                --    self:OpenDialogAction(Constants.UITypeIds.UICompositeEntryDialog, {}, nil, true)
                --end)
            elseif systemToggleId == Constants.SystemToggleIds.Id200 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.Backpack, { { id = Constants.UITypeIds.UIHomeView } }, {type = 1})
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id201 then
                self:SetReverseButtonAction(go, function()
                    xRecord.record('3-006')
                    self:OpenDialogAction(Constants.UITypeIds.MailBox, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id907 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.IllustratedHandbookEntryDialog, { { id = Constants.UITypeIds.UIHomeView } })
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id250 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.ConvertExchangeDialog, {{ id = Constants.UITypeIds.UIHomeView }})
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id260 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.FightTeamPresetDialog, {{ id = Constants.UITypeIds.UIHomeView }})
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id2018 then
                self:SetReverseButtonAction(go, function()
                    self:OpenDialogAction(Constants.UITypeIds.OverseaRankPageDialog, {{ id = Constants.UITypeIds.UIHomeView }})
                end)
            elseif systemToggleId == Constants.SystemToggleIds.Id350 then
                self:SetReverseButtonAction(go, function()
                    ---@type SDKService
                    local SDKService = import('Game.Entry.SDKService')
                    if SDKService:IsZm() then
                        GameUtils.SetRedPointNum(Constants.RedPointConst.ConnectSever , 0)
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.ConnectSever)
                        SDKService:GetInstance():showAllFAQSections({entranceId = "E002" ,deleteCache = "1"} )
                        local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
                        PlayerPrefsUtility.SetEncryptedString("AIHelperNewMessage", "0")
                        PlayerPrefsUtility.Save()
