                return 
            end
            local desc = GameUtils.GetUnlockDescrBySystemTogId(systemToggleId)
            GameUtils.Toast(desc)
        end)
    end
end

function HomeOtherNode:RefreshStatus()
    local baseName = self.ButtonNode.name
    for luaIndex = 1, self.LoopListView.ItemTotalCount do
        local pageData = self.pagesData[luaIndex]
        local pageCell = self.LoopListView:GetShownItemByIndex(luaIndex - 1)
        if isNotNull(pageCell) then
            local gridNode = pageCell.transform:Find("FunctionIconGrid")
            for _, v in ipairs(pageData) do
                local systemToggleId = parse_number(v, "id")
                local buttonName     = string.format("%s%s", baseName, systemToggleId)
                local buttonTrans    = gridNode:Find(buttonName)
                self:RefreshOtherButtonStatus(buttonTrans, systemToggleId)
            end
        end
    end
end


function HomeOtherNode:RefreshOtherButtonStatus(buttonTrans, systemToggleId)
    local isShowBtnNew = false
    if isNotNull(buttonTrans) then
        -- 检测图鉴是否需要显示 new 状态
        if systemToggleId == Constants.SystemToggleIds.Id907 then
            ---@type IllustratedHandbookComponent
            local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
            if isShowBtnNew == false and illustratedHandbookComp:CheckHandbookRoleRedPoint() then  -- [卡牌档案：角色]
                isShowBtnNew = true
            end
            if isShowBtnNew == false and illustratedHandbookComp:CheckHandbookSkinRedPoint() then  -- [卡牌档案：皮肤]
                isShowBtnNew = true
            end
            if isShowBtnNew == false and illustratedHandbookComp:CheckHandbookCatRedPoint() then  -- [卡牌档案：猫种]
                isShowBtnNew = true
            end
            if isShowBtnNew == false and illustratedHandbookComp:CheckHandbookCatBallRedPoint() then -- [猫球档案]
                isShowBtnNew = true
            end
            if isShowBtnNew == false then
                for _, encyDojo in pairs(illustratedHandbookComp:GetRegionMapEncyDojoMap()) do  -- [区域介绍]
                    if encyDojo.isNewMark then
                        isShowBtnNew = true
                        break
                    end
                end
            end
            if isShowBtnNew == false then
                for _, encyDojo in pairs(illustratedHandbookComp:GetKeywordsEncyDojoMap()) do  -- [组织百科、名词百科]
                    if encyDojo.isNewMark then
                        isShowBtnNew = true
                        break
                    end
                end
            end
            CfUtils.SetActive(buttonTrans:Find("ImgNew"), isShowBtnNew)
        end
    end
end


