--MainMenuAction
---@param id number 打开对话框的id
---@param excludeDialogs table 要关闭的列表的逻辑
---@param par table 要关闭的列表的逻辑
---@param isShowScene boolean 要关闭的列表的逻辑
---@param isShowAnim boolean 是否显示animation
function HomeOtherNode:OpenDialogAction(id, excludeDialogs, par, isShowScene, isShowAnim)
    if checkBool(isShowAnim) then
        CfUtils.ShowSwitchAnimation()
    end
    UIRaycastBlocker:AddCondition("OpenDialogAction")
    return cs_coroutine.start(function()
        xTry(function()
            --- 打断角色语音
            CriWareUtils_.PlayVoice("Audio/UI_Menu", "empty")
            CS.UINavigationBarRoot.Instance:SetActive(true)

            coroutine.yield(UIModule.OpenDialog({ id = id, parameters = par }, checkTable(excludeDialogs)))

            if id == Constants.UITypeIds.CultivateEntry or id == Constants.UITypeIds.UINoticeDialog then
            elseif isShowScene then
                Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
            end
            if not isShowScene then
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            end
            --CS.UINavigationBarRoot.Instance:SetActive(true)
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
        end, function()
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
        end)
    end)
end

function HomeOtherNode:OnEnable()
    local timeStr = checkString(os.date('%H:%M'))
    CfUtils.FillText(self.TxtTime, timeStr)
    CfUtils.SetTopCommonActive(false, false)
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function()
            self:Update()
        end
        self._behaviourAction = behaviourAction
    end

    -- 刷新按钮
    if isNotNull(self.btnList) then
        for systemToggleId, go in pairs(self.btnList) do
            self:RefreshBtn(go, systemToggleId)
        end
    end

    -- 把滚动页面设置到第一页
    local listContent = self.LoopListView.transform:Find("Viewport/Content")
    listContent.localPosition = Vector3.zero
    -- 第一页播放入场动画
    local page1 = listContent.transform:Find(PageCellName .. "1")
    if isNotNull(page1) then
        local animCell = page1:GetComponent(typeof(CS.UnityEngine.Animation))
        animCell:Play("UIHomeView_OtherButtonPOP_ItemCell_Entry")
    end

    self:RefreshStatus()
end

function HomeOtherNode:OnDisable()
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
end

function HomeOtherNode:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self._cacheRectTrans, position,
                    UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                KTool.SetActive(self.controller.gameObject, false)
                CfUtils.SetTopCommonActive(false, true)
                KTool.SetActive(self.rightPanelTrans.gameObject, true)
            end
        end
    end
    local time = os.time()
    if (time - self.time) >= TIME then
        self.time = time
        local timeStr = checkString(os.date('%H:%M'))
        CfUtils.FillText(self.TxtTime, timeStr)
        local level = num_floor(SystemInfo.batteryLevel * 5)
        for i = 1, BATTERY_LEVEL do
            local go = self["ImgEnergy" .. i].gameObject
            if i <= level then
                KTool.SetActive(go, true)
            else
                KTool.SetActive(go, false)
            end
        end
        ---处理信号
        level = math.max(1, math.ceil((200 - KNManager.ping) / 50))
        for i = 1, SIGNAL_LEVEL do
            local go = self["Image" .. i].gameObject
            if i <= level then
                KTool.SetActive(go, true)
            else
                KTool.SetActive(go, false)
            end
        end
    end
end


---设置子节点与父亲节点同事事件的逻辑
---@param rootNode UnityEngine.RectTransform
---@param cb fun(event:table):void
function HomeOtherNode:SetReverseButtonAction(rootNode, cb)
    if not rootNode or isNull(rootNode) then
        return
    end

    local go = rootNode.gameObject
    SetButtonAction(rootNode.gameObject, cb)

    local goName = go.name
    ---@type Game.Native.Common.SystemToggle
    local systemToggleScr = KTool.GetComponent(go, typeof(SystemToggle))
    if systemToggleScr then
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(checkString(systemToggleScr.id))
        --KTool.SetActive(go.transform:Find("LockNode"), not isUnlock)
        ---@type Engine.UI.UIAllChildGrayGraphics
        local allUIGrays = KTool.GetComponent(go.gameObject, typeof(CS.Engine.UI.UIAllChildGrayGraphics))
        if not isNull(allUIGrays) then
            allUIGrays:MarkGray(not isUnlock)
        end
        ---主线的逻辑情况下处理
        if checkNumber(systemToggleScr.id) == Constants.SystemToggleIds.Id2 then
            KTool.SetActive(go.transform:Find("AnimRoot/ActiveNode"), isUnlock)
            KTool.SetActive(go.transform:Find("AnimRoot/BtnBg/UIFX_Frame_MarkGray"), not isUnlock)
            KTool.SetActive(go.transform:Find("AnimRoot/BtnBg/UIFX_Frame"), isUnlock)
        else
            KTool.SetActive(go.transform:Find("ActiveNode"), isUnlock)
            KTool.SetActive(go.transform:Find(string.format('%s/UIFX_Frame_MarkGray', goName)), not isUnlock)
            KTool.SetActive(go.transform:Find(string.format('%s/UIFX_Frame', goName)), isUnlock)
        end
        local canvasGroup = KTool.GetComponent(go.gameObject, typeof(CanvasGroup))
        if not isNull(canvasGroup) then
            --if not isUnlock then
            --    canvasGroup.alpha = 0.5
            --else
            canvasGroup.alpha = 1
            --end
        end

        local titleGo = go.transform:Find("TitleText")
        if titleGo then
            local switchText = KTool.GetComponent(titleGo.gameObject, typeof(UISwitchText))
            if switchText then
                switchText.Status = (isUnlock and 1 or 2)
            end
        end

        local switchImg = KTool.GetComponent(go, typeof(UISwitchImage))
        if switchImg then
            switchImg.Status = (isUnlock and 1 or 2)
        end

        local imgIconGo = go.transform:Find("ImgIcon")
        if imgIconGo then
            local c = isUnlock and XLuaUtils.HexToColor('#FFFFFF') or XLuaUtils.HexToColor('#BCBCBC')
            local goIma = imgIconGo.transform:GetComponent(typeof(Image))
            if goIma then
                goIma.color = c
            end
        end

        --商店有特殊的外发光
        if checkNumber(systemToggleScr.id) == Constants.SystemToggleIds.Id150 then
            --local textOutLine = KTool.GetComponent(titleGo.gameObject, typeof(UguiRichOutline))
            if isUnlock then
                --textOutLine.effectColor = Color(255/255, 186/255, 93/255, 56/255)
                KTool.SetActive(go.transform:Find("ImgLight"), true)
            else
                --textOutLine.effectColor = Color(19/255, 19/255, 19/255, 1)
                KTool.SetActive(go.transform:Find("ImgLight"), false)
            end
        end
    end
end

function HomeOtherNode:OnDestroy()
    for _, redKey in pairs(self._otherRedPointMap or {}) do
        GameUtils.RemoveRedPointCallBack(redKey)
    end
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Music)
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeOtherNode